#!/usr/bin/env python3
"""Batch report: a status page per Xtrium pull, built from live data. Run from the repo root (the folder that holds backend/ and frontend/).
Safe to run twice: files already applied are skipped."""
import os, sys, zlib, base64
sys.stdout.reconfigure(errors='replace')
NEW = {'backend/app/services/batch_report.py': '', 'frontend/src/components/enh/BatchReport.tsx': ''}
MOD = {'backend/app/api/v1/routes/quality.py': [('    return Response(content=body, media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", headers={"Content-Disposition": f\'attachment; filename="sop_requirements_{stamp}.xlsx"\'})\n', '    return Response(content=body, media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet", headers={"Content-Disposition": f\'attachment; filename="sop_requirements_{stamp}.xlsx"\'})\n\n\n# ─── Batch report: one page per Xtrium pull, built from live data ────────────\n\n@router.get("/batch-report/list")\ndef batch_report_list(project_id: str | None = None, db: Session = Depends(get_db), user: User = Depends(get_current_user)):\n    from app.services import batch_report as br\n    _need_lead(user)\n    return {"batches": br.list_batches(_visible_sources(db, user, project_id).all())}\n\n\n@router.get("/batch-report")\ndef batch_report(batch: str, project_id: str | None = None, db: Session = Depends(get_db), user: User = Depends(get_current_user)):\n    """Everything about the sources Xtrium gave on one day: progress, what is blocked and what we need, people, and accuracy."""\n    from app.services import batch_report as br\n    _need_lead(user)\n    srcs = _visible_sources(db, user, project_id).all()\n    try:\n        sc, _ = _scorecard_data(db, user, project_id, None, None, None)\n    except Exception:\n        sc = None\n    return br.assemble(db, user, srcs, batch, sc)\n')], 'frontend/src/api/client.ts': [("  feedback: (sourceId: string) => api.get(`/quality/sources/${sourceId}/feedback`).then(r => r.data),\n  extractorReport: (params: { project_id?: string; source_id?: string; user_id?: string; days?: number; date_from?: string; date_to?: string }) => api.get('/quality/extractor-report', { params }).then(r => r.data),\n  processReport: (params: { project_id?: string; source_id?: string; date_from?: string; date_to?: string }) => api.get('/quality/process-report', { params }).then(r => r.data),\n  exportProcessReport: async (params: { project_id?: string; source_id?: string; date_from?: string; date_to?: string }) => {", "  feedback: (sourceId: string) => api.get(`/quality/sources/${sourceId}/feedback`).then(r => r.data),\n  extractorReport: (params: { project_id?: string; source_id?: string; user_id?: string; days?: number; date_from?: string; date_to?: string }) => api.get('/quality/extractor-report', { params }).then(r => r.data),\n  batchList: (project_id?: string) => api.get('/quality/batch-report/list', { params: { project_id } }).then(r => r.data),\n  batchReport: (batch: string, project_id?: string) => api.get('/quality/batch-report', { params: { batch, project_id } }).then(r => r.data),\n  processReport: (params: { project_id?: string; source_id?: string; date_from?: string; date_to?: string }) => api.get('/quality/process-report', { params }).then(r => r.data),\n  exportProcessReport: async (params: { project_id?: string; source_id?: string; date_from?: string; date_to?: string }) => {")], 'frontend/src/pages/Quality.tsx': [("import { FinalCheck } from '@/components/enh/FinalCheck'\nimport { RoundsReport } from '@/components/enh/RoundsReport'\nimport { ProcessReport } from '@/components/enh/ProcessReport'\nimport { ReviewWorkspace } from '@/components/enh/ReviewWorkspace'", "import { FinalCheck } from '@/components/enh/FinalCheck'\nimport { RoundsReport } from '@/components/enh/RoundsReport'\nimport { BatchReport } from '@/components/enh/BatchReport'\nimport { ProcessReport } from '@/components/enh/ProcessReport'\nimport { ReviewWorkspace } from '@/components/enh/ReviewWorkspace'"), ("const err = (e: any, d: string) => e?.response?.data?.detail || d\n\ntype Tab = 'review' | 'scores' | 'sop' | 'findings' | 'audit' | 'final' | 'rounds'\n\nexport function QualityPage() {", "const err = (e: any, d: string) => e?.response?.data?.detail || d\n\ntype Tab = 'review' | 'scores' | 'sop' | 'findings' | 'audit' | 'final' | 'rounds' | 'batch'\n\nexport function QualityPage() {"), ('      <PageHeader title="Quality" subtitle={tab === \'review\' && bench ? undefined : "How accurate the delivered data is, how many errors reviewers caught, and how many got through. Scores come from errors that were checked and from fields an admin verified against the real source."} />\n      <div className="flex items-center gap-3 flex-wrap">\n        <Tabs value={tab} onChange={t => { setTab(t) }} items={[{ key: \'review\', label: \'Review\' }, { key: \'scores\', label: \'Scores\' }, { key: \'sop\', label: \'SOP check\' }, { key: \'findings\', label: \'Errors logged\', count: (sources ?? []).reduce((n, s) => n + s.open_findings, 0) }, { key: \'audit\', label: \'Check against source\' }, { key: \'final\', label: \'Final check\' }, { key: \'rounds\', label: \'v1 vs v2\' }]} />\n        {tab !== \'review\' && <SelectBox label="Project" value={projectId} onChange={v => { setProjectId(v); setSourceId(\'\') }}>\n          <option value="">All projects</option>\n          {projects.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}\n        </SelectBox>}\n        {tab !== \'review\' && <SelectBox label="Source" value={sourceId} onChange={setSourceId}>\n          <option value="">All sources</option>\n          {(sources ?? []).filter(s => !projectId || s.project_id === projectId).map(s => <option key={s.source_id} value={s.source_id}>{s.name}{s.open_findings ? ` (${s.open_findings} open)` : \'\'}</option>)}', '      <PageHeader title="Quality" subtitle={tab === \'review\' && bench ? undefined : "How accurate the delivered data is, how many errors reviewers caught, and how many got through. Scores come from errors that were checked and from fields an admin verified against the real source."} />\n      <div className="flex items-center gap-3 flex-wrap">\n        <Tabs value={tab} onChange={t => { setTab(t) }} items={[{ key: \'review\', label: \'Review\' }, { key: \'scores\', label: \'Scores\' }, { key: \'sop\', label: \'SOP check\' }, { key: \'findings\', label: \'Errors logged\', count: (sources ?? []).reduce((n, s) => n + s.open_findings, 0) }, { key: \'audit\', label: \'Check against source\' }, { key: \'final\', label: \'Final check\' }, { key: \'rounds\', label: \'v1 vs v2\' }, { key: \'batch\', label: \'Batch report\' }]} />\n        {tab !== \'review\' && <SelectBox label="Project" value={projectId} onChange={v => { setProjectId(v); setSourceId(\'\') }}>\n          <option value="">All projects</option>\n          {projects.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}\n        </SelectBox>}\n        {tab !== \'review\' && tab !== \'batch\' && <SelectBox label="Source" value={sourceId} onChange={setSourceId}>\n          <option value="">All sources</option>\n          {(sources ?? []).filter(s => !projectId || s.project_id === projectId).map(s => <option key={s.source_id} value={s.source_id}>{s.name}{s.open_findings ? ` (${s.open_findings} open)` : \'\'}</option>)}'), ("      {tab === 'final' && <FinalCheck projectId={projectId} sourceId={sourceId} />}\n      {tab === 'rounds' && <RoundsReport projectId={projectId} sourceId={sourceId} />}\n    </div>\n  )", "      {tab === 'final' && <FinalCheck projectId={projectId} sourceId={sourceId} />}\n      {tab === 'rounds' && <RoundsReport projectId={projectId} sourceId={sourceId} />}\n      {tab === 'batch' && <BatchReport projectId={projectId} />}\n    </div>\n  )")]}
root = os.getcwd()
if not (os.path.isdir(os.path.join(root, 'backend')) and os.path.isdir(os.path.join(root, 'frontend'))):
    sys.exit('Run this from the repo root (the folder containing backend and frontend).')
def rd(p): return open(p, encoding='utf-8', newline='').read()
done = skipped = 0; bad = []
for rel, hunks in MOD.items():
    p = os.path.join(root, rel)
    if not os.path.exists(p): bad.append(rel + ' (missing)'); continue
    raw = rd(p); crlf = '\r\n' in raw; t = raw.replace('\r\n', '\n'); changed = False
    for old, new in hunks:
        if new in t: continue
        elif t.count(old) == 1: t = t.replace(old, new); changed = True
        else: bad.append(rel + ' (a section does not match; file differs from expected version)'); break
    else:
        if changed:
            open(p, 'w', encoding='utf-8', newline='').write(t.replace('\n', '\r\n') if crlf else t); done += 1; print('updated ', rel)
        else: skipped += 1
for rel, blob in NEW.items():
    p = os.path.join(root, rel); data = zlib.decompress(base64.b64decode(blob))
    if os.path.exists(p) and open(p, 'rb').read() == data: skipped += 1; continue
    os.makedirs(os.path.dirname(p), exist_ok=True); open(p, 'wb').write(data); done += 1; print('wrote   ', rel)
print(f'\n{done} changed, {skipped} already applied.')
if bad:
    print('\nPROBLEMS:'); [print(' -', b) for b in bad]; sys.exit(1)
